begin;

insert into public.content_pages
(slug,title,eyebrow,lead,intro,points,lesson,practice,next_step,sort_order,is_published)
values
('meditation','مدیتیشن و مراقبه','آموزش تخصصی • مدیتیشن و مراقبه','تمرینی برای بازگشت توجه به لحظه اکنون و مشاهده آرام تجربه درونی.','مدیتیشن مجموعه‌ای از تمرین‌های توجه و آگاهی است. قرار نیست ذهن را به زور خالی کنی یا تجربه خاصی بسازی؛ هدف، دیدن آن چیزی است که اکنون وجود دارد و بازگرداندن آرام توجه هر بار که حواس پرت می‌شود.','["آشنایی با مراقبه تنفس و توجه به بدن","تمرین مشاهده افکار بدون درگیری با آن‌ها","مراقبه کوتاه برای شروع روز یا پایان شب","ساختن عادت تمرین کوتاه و منظم"]'::jsonb,'در جای امن و راحت بنشین. چشم‌ها را باز یا بسته نگه دار؛ هرکدام که برایت راحت‌تر است. چند لحظه تماس بدن با صندلی یا زمین را حس کن. سپس توجهت را به تنفس طبیعی بده. هر وقت متوجه شدی ذهنت منحرف شده، بدون سرزنش توجه را به تنفس برگردان. دو تا پنج دقیقه کافی است.','برای هفت روز، روزانه سه دقیقه در زمان ثابتی مراقبه ساده تنفس انجام بده. اگر تمرکز روی تنفس برایت ناخوشایند است، به صداهای محیط یا تماس پاها با زمین توجه کن و هر زمان ناراحتی ادامه داشت تمرین را متوقف کن.','در همین صفحه فایل‌های صوتی و تصویری مدیتیشن پس از انتشار نمایش داده می‌شوند.',8,true),
('chakra','پاکسازی و تعادل چاکراها','آموزش تخصصی • شناخت چاکراها','آشنایی با مفهوم چاکراها در سنت‌های معنوی و استفاده از تمرین‌های ملایم برای توجه به بدن و احساسات.','چاکراها مفهومی در برخی سنت‌های معنوی هند هستند و به‌عنوان مراکز انرژی توصیف می‌شوند؛ این مدل، چارچوبی معنوی و نمادین است و جایگزین دانش پزشکی یا تشخیص اختلال جسمی و روانی نیست. در این بخش به‌جای وعده پاکسازی قطعی یا درمان، از تمرین‌های امن خودآگاهی، تنفس طبیعی و تأمل استفاده می‌کنیم.','["آشنایی مقدماتی با هفت چاکرا در سنت‌های یوگا","بررسی نمادها و موضوعات منتسب به هر مرکز","توجه ملایم به وضعیت بدن، احساسات و نیازها","پرهیز از ادعای درمان یا تشخیص بر اساس چاکراها"]'::jsonb,'برای شروع، از پایین‌تنه تا بالاتنه توجهت را آرام جابه‌جا کن: پاها، شکم، قفسه سینه، گلو و صورت. در هر ناحیه فقط حس‌های موجود را مشاهده کن؛ لازم نیست رنگ، گرما یا انرژی خاصی احساس کنی. اگر درد، سرگیجه یا اضطراب ایجاد شد، تمرین را متوقف کن و به محیط اطراف توجه کن.','یک دفترچه بردار و پس از یک مکث دو دقیقه‌ای بنویس: اکنون در بدنم چه حسی دارم؟ چه احساسی را تجربه می‌کنم؟ به چه نیازی باید توجه کنم؟ این تمرین را به‌عنوان خودمشاهده‌گری انجام بده، نه سنجش وضعیت پزشکی یا انرژی بدن.','تمرین‌های صوتی و تصویری این موضوع، در صورت انتشار، فقط در همین صفحه نمایش داده می‌شوند.',9,true),
('kundalini','بیداری کندالینی','آموزش تخصصی • شناخت کندالینی','شناخت مفهوم کندالینی در سنت یوگا، همراه با آگاهی از احتیاط‌ها و پرهیز از تحریک شتاب‌زده.','کندالینی مفهومی معنوی در برخی سنت‌های یوگا و تانتراست که با نماد انرژی نهفته توصیف می‌شود. تجربه‌های شدید جسمی یا روانی را نباید خودبه‌خود نشانه بیداری معنوی دانست. این مسیر نیازمند مطالعه، ثبات روانی، تمرین تدریجی و راهنمایی مسئولانه است؛ از روش‌های افراطی یا وعده‌های فوری دوری کن.','["ریشه و معنای کندالینی در سنت‌های معنوی","تفاوت روایت‌های سنتی با ادعاهای اثبات‌نشده","اهمیت خواب، تغذیه، تعادل و تمرین پایه","شناخت نشانه‌های فشار و زمان توقف تمرین"]'::jsonb,'پیش از هر تمرین پیشرفته، روی پایه‌ها تمرکز کن: خواب منظم، فعالیت بدنی متعادل، تنفس طبیعی و توانایی بازگشت توجه به محیط. از حبس طولانی نفس، تنفس‌های شدید، روزه‌داری افراطی یا تلاش برای ایجاد تجربه‌های غیرعادی بدون راهنمایی متخصص پرهیز کن.','برای یک هفته فقط یک تمرین ساده حضور در لحظه یا مراقبه کوتاه و بدون فشار انجام بده. وضعیت خواب، خلق و انرژی روزانه‌ات را ثبت کن. اگر بی‌خوابی، آشفتگی شدید، ترس یا احساس گسست ایجاد شد، تمرین را متوقف کن و از متخصص سلامت کمک بگیر.','این صفحه برای آموزش و شناخت سنت‌هاست و دستورالعمل تحریک انرژی یا درمان پزشکی ارائه نمی‌کند.',10,true),
('fengshui','فنگ‌شویی و هماهنگی فضای زندگی','آموزش کاربردی • فنگ‌شویی','با نظم، نور، جریان حرکت و چیدمان سنجیده، فضایی آرام‌تر و کاربردی‌تر بساز.','فنگ‌شویی سنتی چینی درباره چیدمان و هماهنگی محیط است. برداشت‌ها و مکاتب مختلفی دارد و ادعاهای ماورایی یا تضمین تغییر سرنوشت از راه چیدمان، پشتوانه علمی قطعی ندارند. با این حال، نور مناسب، نظم، تهویه و مسیر رفت‌وآمد راحت می‌توانند کیفیت استفاده از فضا را بهتر کنند.','["خلوت‌کردن ورودی و مسیرهای رفت‌وآمد","استفاده از نور طبیعی و روشنایی متعادل","چیدمان کاربردی مبلمان و ایجاد فضای تنفس","انتخاب رنگ و اشیای هماهنگ با نیاز و سلیقه ساکنان"]'::jsonb,'از ورودی خانه شروع کن. کف و مسیر حرکت را خلوت نگه دار، وسایل پرکاربرد را در دسترس قرار بده و نور ورودی را بررسی کن. سپس یک گوشه کوچک برای آرامش یا مطالعه بساز؛ فضایی که واقعاً استفاده می‌کنی و نگهداری از آن ساده است.','امروز فقط یک محدوده کوچک را انتخاب کن؛ مثلاً میز کنار تخت یا ورودی خانه. وسایل غیرضروری را بردار، سطح را تمیز کن و نور و مسیر حرکت را بهتر کن. بعد از یک هفته بررسی کن آیا استفاده از فضا برایت راحت‌تر شده است.','در این بخش می‌توانی راهنماهای تصویری، نمونه چیدمان و فایل‌های آموزشی فنگ‌شویی را دنبال کنی.',11,true)
on conflict (slug) do update set
 title=excluded.title,eyebrow=excluded.eyebrow,lead=excluded.lead,intro=excluded.intro,
